from pathlib import Path
import csv,json,collections
R=Path(__file__).resolve().parents[1]
def read(n):
 with (R/'data'/n).open(encoding='utf-8-sig',newline='') as f:return list(csv.DictReader(f))
def write(n,rs):
 with (R/'data'/n).open('w',encoding='utf-8-sig',newline='') as f:w=csv.DictWriter(f,fieldnames=list(rs[0]));w.writeheader();w.writerows(rs)
